template:
mod convert {
    pub trait Distance {
        fn to_meters(&self) -> f64;
    }

    impl Distance for f64 {
        fn to_meters(&self) -> f64 {
            *self * 1000.0
        }
    }
}

⟦slot1⟧ convert::⟦slot2⟧;

fn total_meters(km: f64) -> f64 {
    km.to_meters()
}

fn main() {
    assert_eq!(total_meters(2.5), 2500.0);
}
